# AUTO-GENERATED BY THE PIPELINE. Do not edit or delete: it is rewritten on every pass.
#
# start.sh builds the database with `alembic upgrade head`. The rest of this
# suite usually builds it with `Base.metadata.create_all()`, which never runs a
# migration. These tests run the migrations the way start.sh does, on an EMPTY
# SQLite file, then ask alembic whether the result matches the models.
#
# If one fails, fix the MIGRATIONS, not this file and not the database:
#   - SQLite cannot ALTER a column or a constraint. Put alter_column,
#     create_foreign_key, drop_constraint, create_unique_constraint and friends
#     inside `with op.batch_alter_table("<table>") as batch_op:`.
#     `render_as_batch=True` in env.py only affects AUTOGENERATED migrations.
#   - A model change needs a new revision that makes the same change.
#   - UUID columns must be `sqlalchemy.Uuid` / `sa.Uuid()`, not the PostgreSQL
#     `UUID` type: SQLite turns a digits-only UUID into an integer.
#   - A UUID id is `Mapped[uuid.UUID]` + `Uuid` everywhere, foreign keys included:
#     a `uuid.UUID` cannot go into a text column, nor a `str` into a `Uuid` one.
import ast
import configparser
import os
import sqlite3
import subprocess
import sys
from pathlib import Path

import pytest

_BACKEND = Path(__file__).resolve().parent.parent
_RUNNER = """
import logging
import sys
# The per-difference "Detected ..." lines are INFO logs; not every alembic.ini
# configures logging.
logging.basicConfig(level=logging.INFO, format="%(levelname)s [%(name)s] %(message)s")
from alembic import command
from alembic.config import Config
cfg = Config("alembic.ini")
cfg.set_main_option("sqlalchemy.url", sys.argv[2].replace("%", "%%"))
if sys.argv[1] == "upgrade":
    command.upgrade(cfg, "head")
else:
    command.check(cfg)
"""


def _env_py_text():
    parser = configparser.ConfigParser(interpolation=None)
    try:
        parser.read(_BACKEND / "alembic.ini", encoding="utf-8")
        location = parser.get("alembic", "script_location", fallback="alembic")
    except (configparser.Error, OSError):
        location = "alembic"
    location = location.replace("%(here)s", str(_BACKEND))
    env_py = Path(location)
    if not env_py.is_absolute():
        env_py = _BACKEND / env_py
    try:
        return (env_py / "env.py").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def _alembic(action, url):
    env = dict(os.environ, DATABASE_URL=url)
    proc = subprocess.run(
        [sys.executable, "-c", _RUNNER, action, url],
        cwd=_BACKEND, env=env, capture_output=True, text=True, timeout=300,
    )
    return proc.returncode, proc.stdout + proc.stderr


@pytest.fixture(scope="module")
def migrated(tmp_path_factory):
    db = tmp_path_factory.mktemp("migration_parity") / "app.db"
    is_async = any(
        marker in _env_py_text()
        for marker in ("async_engine_from_config", "create_async_engine", "AsyncEngine")
    )
    url = ("sqlite+aiosqlite:///" if is_async else "sqlite:///") + db.as_posix()
    code, output = _alembic("upgrade", url)
    if code == 0 and not _has_alembic_version(db):
        # env.py read its URL from somewhere else (a settings field, a hard-coded
        # path), so the run migrated whatever database that names, not this file.
        code, output = 1, (
            "`alembic upgrade head` succeeded but did not touch the database it was given "
            "through DATABASE_URL and sqlalchemy.url. env.py takes its URL from somewhere "
            "else, so these tests cannot check the migrations, and start.sh's exported "
            "DATABASE_URL is ignored the same way. Make env.py use DATABASE_URL.\n" + output
        )
    return url, (code, output)


def _has_alembic_version(db):
    if not db.exists():
        return False
    conn = sqlite3.connect(str(db))
    try:
        row = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='alembic_version'"
        ).fetchone()
    finally:
        conn.close()
    return row is not None


def test_migrations_build_an_empty_database(migrated):
    _url, (code, output) = migrated
    assert code == 0, (
        "`alembic upgrade head` fails on an empty SQLite database, so start.sh fails on "
        "every fresh checkout. Fix the migration in the traceback below. On SQLite, alter "
        "columns and constraints inside `with op.batch_alter_table(...)`.\n" + output[-4000:]
    )


def test_migrations_match_the_models(migrated):
    url, (code, _output) = migrated
    if code != 0:
        pytest.skip("the migrations do not apply; see test_migrations_build_an_empty_database")
    check_code, output = _alembic("check", url)
    if check_code != 0 and (
        "does not provide a MetaData object" in output or "has no attribute 'check'" in output
    ):
        pytest.skip("alembic cannot compare this project's models: " + output.strip()[-300:])
    # alembic logs one "Detected ..." line per difference, then repeats them all
    # in one unreadable exception. The lines are the useful part.
    detected = [line.split("] ", 1)[-1] for line in output.splitlines() if "Detected " in line]
    assert check_code == 0, (
        "The database `alembic upgrade head` builds does not match the models, so the app "
        "start.sh launches lacks tables, columns, indexes or constraints the code declares. "
        "Add a migration revision for every difference below (do not edit an applied one).\n"
        + ("\n".join(detected) if detected else output[-4000:])
    )


def test_uuid_columns_are_stored_as_text(migrated):
    url, (code, _output) = migrated
    if code != 0:
        pytest.skip("the migrations do not apply; see test_migrations_build_an_empty_database")
    conn = sqlite3.connect(url.split(":///", 1)[1])
    try:
        tables = [
            row[0]
            for row in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
            )
        ]
        numeric_uuid = [
            f"{table}.{column[1]}"
            for table in tables
            for column in conn.execute(f'PRAGMA table_info("{table}")')
            if (column[2] or "").strip().upper() == "UUID"
        ]
    finally:
        conn.close()
    assert not numeric_uuid, (
        "These columns are declared `UUID`, which SQLite stores with NUMERIC affinity: a UUID "
        "written as digits only (00000000-0000-0000-0000-000000000001) is saved as the integer 1, "
        "and reading the row back fails with `'int' object has no attribute 'replace'`. "
        "`sqlalchemy.dialects.postgresql.UUID` and `sa.UUID()` both create this type. Use "
        "`sqlalchemy.Uuid` (`from sqlalchemy import Uuid`, `mapped_column(Uuid, ...)`) in the "
        "models and `sa.Uuid()` in the migrations; it is stored as CHAR(32) text on SQLite and "
        "as a native uuid on PostgreSQL.\n" + "\n".join(numeric_uuid)
    )


# Read from the source, not by importing the app: a model that does not import
# yet must not hide the mismatch.
_SKIP_DIRS = {".venv", "venv", "node_modules", "alembic", "migrations", "tests", "__pycache__"}
_TEXT_TYPES = {"String", "VARCHAR", "CHAR", "NCHAR", "NVARCHAR", "Text", "Unicode", "UnicodeText"}
_UUID_TYPES = {"Uuid", "UUID"}


def _last_name(node):
    if isinstance(node, ast.Call):
        node = node.func
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    return None


def _annotation_kind(annotation):
    """'uuid' or 'str' for Mapped[uuid.UUID] / Mapped[str] (Optional or `| None` too)."""
    if not (isinstance(annotation, ast.Subscript) and _last_name(annotation.value) == "Mapped"):
        return None
    inner = annotation.slice
    while True:
        if isinstance(inner, ast.BinOp) and isinstance(inner.op, ast.BitOr):
            sides = [s for s in (inner.left, inner.right) if not (isinstance(s, ast.Constant) and s.value is None)]
            if len(sides) != 1:
                return None
            inner = sides[0]
        elif isinstance(inner, ast.Subscript) and _last_name(inner.value) == "Optional":
            inner = inner.slice
        else:
            break
    name = _last_name(inner)
    return "uuid" if name == "UUID" else "str" if name == "str" else None


def _column_kind(call):
    """'uuid' / 'str' for the column type mapped_column() is given, None if none or other."""
    for arg in call.args:
        if isinstance(arg, ast.Constant) or _last_name(arg) == "ForeignKey":
            continue
        name = _last_name(arg)
        if name in _UUID_TYPES:
            as_uuid = [k.value for k in getattr(arg, "keywords", []) if k.arg == "as_uuid"]
            if as_uuid and isinstance(as_uuid[0], ast.Constant) and as_uuid[0].value is False:
                return "str"
            return "uuid"
        return "str" if name in _TEXT_TYPES else None
    return None


def _foreign_key(call):
    for arg in call.args:
        if isinstance(arg, ast.Call) and _last_name(arg) == "ForeignKey" and arg.args:
            target = arg.args[0]
            if isinstance(target, ast.Constant) and isinstance(target.value, str):
                return target.value
    return None


def _mapped_columns():
    for path in sorted(_BACKEND.rglob("*.py")):
        if _SKIP_DIRS.intersection(path.relative_to(_BACKEND).parts[:-1]):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for cls in [n for n in ast.walk(tree) if isinstance(n, ast.ClassDef)]:
            table = None
            for stmt in cls.body:
                if (
                    isinstance(stmt, ast.Assign)
                    and any(isinstance(t, ast.Name) and t.id == "__tablename__" for t in stmt.targets)
                    and isinstance(stmt.value, ast.Constant)
                ):
                    table = stmt.value.value
            for stmt in cls.body:
                if not (
                    isinstance(stmt, ast.AnnAssign)
                    and isinstance(stmt.target, ast.Name)
                    and isinstance(stmt.value, ast.Call)
                    and _last_name(stmt.value) == "mapped_column"
                ):
                    continue
                hint = _annotation_kind(stmt.annotation)
                column = _column_kind(stmt.value)
                yield {
                    "where": f"{path.relative_to(_BACKEND).as_posix()}:{stmt.lineno} {cls.name}.{stmt.target.id}",
                    "table": table,
                    "name": stmt.target.id,
                    "hint": hint,
                    "column": column,
                    "kind": column or hint,
                    "fk": _foreign_key(stmt.value),
                }


def test_uuid_ids_have_one_type_end_to_end():
    columns = list(_mapped_columns())
    by_target = {(c["table"], c["name"]): c for c in columns if c["table"]}
    problems = []
    for c in columns:
        if c["hint"] and c["column"] and c["hint"] != c["column"] and "uuid" in (c["hint"], c["column"]):
            stored = "a Uuid column" if c["column"] == "uuid" else "a text column"
            problems.append(f"{c['where']}: typed Mapped[{'uuid.UUID' if c['hint'] == 'uuid' else 'str'}] but stored in {stored}")
        target = by_target.get(tuple(c["fk"].rsplit(".", 1))) if c["fk"] and "." in c["fk"] else None
        if target and c["kind"] and target["kind"] and c["kind"] != target["kind"] and "uuid" in (c["kind"], target["kind"]):
            problems.append(
                f"{c['where']}: foreign key to {c['fk']} is {'Uuid' if c['kind'] == 'uuid' else 'text'}, "
                f"the key it points at is {'Uuid' if target['kind'] == 'uuid' else 'text'}"
            )
    assert not problems, (
        "UUID ids do not have one type end to end. SQLite cannot store a `uuid.UUID` in a "
        "text column (`Error binding parameter N: type 'UUID' is not supported`), and a `Uuid` "
        "column cannot take a `str` (`'str' object has no attribute 'hex'`), so every id and "
        "every foreign key to it must agree. Use, everywhere: `id: Mapped[uuid.UUID] = "
        "mapped_column(Uuid, primary_key=True, default=uuid.uuid4)` (`from sqlalchemy import "
        "Uuid`), foreign keys `Mapped[uuid.UUID] = mapped_column(Uuid, ForeignKey(...))`, "
        "`sa.Uuid()` in a new migration revision, and `uuid.UUID` values in code (FastAPI "
        "path parameters typed `uuid.UUID`, never `str(uuid.uuid4())`).\n"
        + "\n".join(problems[:40])
        + (f"\n... and {len(problems) - 40} more" if len(problems) > 40 else "")
    )
